// Synthetic Facilio org package pieces for tests (no customer data). Built in code so nothing real is committed.
import { createRequire } from 'node:module'; const require = createRequire(import.meta.url); const JSZip = require('../../vendor/jszip.min.js');
const rec = (type, attrs, inner) => `<${type} Created_Version="1.0" Modified_Version="1.0" Status="ADDED" Type="1" Unique_Identifier="${attrs.uid || 1}" Parent_Id="${attrs.pid || 1}">${inner}</${type}>`;
const wrap = x => `<Components>${x}</Components>`;
export const moduleXml = (list) => wrap(list.map(([n, l, custom], i) => rec('MODULE', { uid: 100 + i }, `<name>${n}</name><Description/><displayName>${l}</displayName><Module_Type>1</Module_Type><IsCustom>${!!custom}</IsCustom><Is_StateFlow_Enabled>true</Is_StateFlow_Enabled><isHiddenModule>false</isHiddenModule>`)).join(''));
export const statusXml = (m, list) => wrap(list.map(([s, l, t], i) => rec('TICKET_STATUS', { uid: 200 + i }, `<parentModuleName>${m}</parentModuleName><displayName>${l}</displayName><recordLocked>false</recordLocked><requestedState>false</requestedState><status>${s}</status><timerEnabled>true</timerEnabled><typeCode>${t || 1}</typeCode>`)).join(''));
export const flowXml = (m, name, link, def, states) => wrap(rec('STATE_FLOW', { uid: 300 }, `<name>${name}</name><Description>Test flow ${name}</Description><moduleName>${m}</moduleName><StateflowLinkName>${link}</StateflowLinkName><Activity_Type>CREATE</Activity_Type><defaultStateflow>false</defaultStateflow><defaultStateName>${def}</defaultStateName><Rule_Type>STATE_FLOW</Rule_Type><draft>false</draft><Execution_Order>1</Execution_Order><Status>true</Status><DiagramElement><States>${states.map(([n, x, y]) => `<State name="${n}" x="${x}" y="${y}"><Anchors/></State>`).join('')}</States></DiagramElement>`));
export const transXml = (m, flowName, link, list) => wrap(list.map(([from, to, name, lk, type, role], i) => rec('STATE_TRANSITION', { uid: 400 + i }, `<moduleName>${m}</moduleName><FromStateName>${from}</FromStateName><ToStateName>${to}</ToStateName><StateflowName>${flowName}</StateflowName><StateflowLinkName>${link}</StateflowLinkName><Type>${type || 1}</Type><name>${name}</name><linkName>${lk}</linkName><Status>true</Status><Activity_Type>STATE_TRANSITION</Activity_Type><Rule_Type>STATE_RULE</Rule_Type><ShowInTenantPortal>false</ShowInTenantPortal><Comment_Required>${i === 0}</Comment_Required>${role ? `<ApproverList><Single_Sharing_Context><Sharing_Type>ROLE</Sharing_Type><Role_Name>${role}</Role_Name></Single_Sharing_Context></ApproverList>` : ''}<ValidationList/>`)).join(''));
export const FLOW = { m: 'workorder', name: 'Package Flow', link: 'packageflow', def: 'submitted', states: [['submitted', 100, 120], ['inprogress', 360, 120], ['resolved', 620, 120], ['closed', 880, 120]],
  trans: [['submitted', 'inprogress', 'Start Work', 'startwork', 1, 'Supervisor'], ['inprogress', 'resolved', 'Resolve', 'resolve', 1, 'Technician'], ['resolved', 'closed', 'Close', 'close', 1, 'Supervisor'], ['resolved', 'inprogress', 'Reopen', 'reopen', 1, 'Ghost Role Not In Project']],
  statuses: [['submitted', 'Submitted'], ['inprogress', 'In Progress'], ['resolved', 'Resolved'], ['closed', 'Closed', 2]] };
export const FLOW_IMPORT = { ...FLOW, name: 'Imported Test Flow', link: 'importedtest', trans: [['submitted', 'inprogress', 'Begin Work', 'beginwork', 1, 'Supervisor'], ['inprogress', 'resolved', 'Finish', 'finish', 1, 'Technician'], ['resolved', 'closed', 'Sign Off', 'signoff', 1, 'Supervisor'], ['resolved', 'inprogress', 'Reopen Job', 'reopenjob', 1, 'Totally New Role']] };
export const flowFiles = (f = FLOW_IMPORT) => ({ 'STATE_FLOW.xml': flowXml(f.m, f.name, f.link, f.def, f.states), 'STATE_TRANSITION.xml': transXml(f.m, f.name, f.link, f.trans), 'TICKET_STATUS.xml': statusXml(f.m, f.statuses) });
export async function packageZip(opts = {}) {
  const z = new JSZip(); const custom = opts.custom || 'custom_widgetx'; const comps = [];
  const add = (type, xml) => { z.file('components/' + type + '.xml', xml); comps.push(type); };
  add('MODULE', moduleXml([['workorder', 'Work Order'], ['asset', 'Assets'], ['serviceRequest', 'Service Request'], [custom, 'Widget Tracker', true]]));
  add('TICKET_STATUS', statusXml('workorder', FLOW.statuses));
  add('STATE_FLOW', flowXml(FLOW.m, FLOW.name, FLOW.link, FLOW.def, FLOW.states)); add('STATE_TRANSITION', transXml(FLOW.m, FLOW.name, FLOW.link, FLOW.trans));
  add('TICKET_PRIORITY', wrap(['High', 'Low'].map((n, i) => rec('TICKET_PRIORITY', { uid: 500 + i }, `<priority>${n}</priority><displayName>${n}</displayName><sequenceNumber>${i + 1}</sequenceNumber>`)).join('')));
  add('GLOBAL_VARIABLE', wrap(rec('GLOBAL_VARIABLE', { uid: 600 }, `<name>apitoken</name><Variable_Name>API Token</Variable_Name><Value_String>SECRET-VALUE-123</Value_String>`) + rec('GLOBAL_VARIABLE', { uid: 601 }, `<name>mainapp</name><Variable_Name>Main App</Variable_Name><Value_String>https://app.example.test</Value_String>`)));
  add('TRIGGER', wrap(rec('TRIGGER', { uid: 700 }, `<Name>Create</Name><Link_Name>create</Link_Name><Module_Name>workorder</Module_Name><Execution_Order>1.0</Execution_Order><Event_Type>CREATE</Event_Type><Status>true</Status><Trigger_Type>MODULE_TRIGGER</Trigger_Type><Is_Default>true</Is_Default>`)));
  add('VIEW', wrap(rec('VIEW', { uid: 800 }, `<name>all</name><moduleName>workorder</moduleName>`) + rec('VIEW', { uid: 801 }, `<name>open</name><moduleName>workorder</moduleName>`)));
  if (opts.broken) { z.file('components/FORM.xml', '<Components><FORM><name>x</FORM>'); comps.push('FORM'); }
  z.file('PackageConf.xml', `<Package><name>synthetic</name><version>1.0</version><type>1</type><Components>${comps.map(c => `<Component Type="${c}">${c}.xml</Component>`).join('')}</Components></Package>`);
  return Buffer.from(await z.generateAsync({ type: 'uint8array' }));
}
export async function notAPackageZip() { const z = new JSZip(); z.file('readme.txt', 'hello'); z.file('data.xml', '<a/>'); return Buffer.from(await z.generateAsync({ type: 'uint8array' })); }
